contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool reverted;
        c.sendMoney(address(this), amount, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(reverted
            ? (countAfter == countBefore && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore)
            : (countAfter == countBefore && cBalAfter + amount == cBalBefore && thisBalAfter == thisBalBefore + amount));
    }

    receive() external payable {}
}

