pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        bool reverted;
        try c.sendMoney(address(this), amount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 countAfter;
        try c.depositsCount() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        assertTrue(reverted
            ? (countAfter == countBefore && cBalAfter == cBalBefore && thisBalAfter == thisBalBefore)
            : (countAfter == countBefore && cBalAfter + amount == cBalBefore && thisBalAfter == thisBalBefore + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
